{% set t = now().strftime("%H:%M") %}
{% if trigger.entity_id == "binary_sensor.klippbok_water_leak_sensor_water_leak" %}
  {% set msg = "💧 [" ~ t ~ "] Living Room Water Leak" %}
{% elif trigger.entity_id == "binary_sensor.ikea_of_sweden_badring_water_leakage_sensor_moisture" %}
  {% set msg = "💧 [" ~ t ~ "] BADRING Water Leak" %}
{% elif trigger.entity_id == "binary_sensor.natgas_sensor_158d00035a8b85" %}
  {% set msg = "🔥 [" ~ t ~ "] Kitchen Gas Leak" %}
{% elif trigger.entity_id == "binary_sensor.smoke_sensor_158d0002ad1027" %}
  {% set msg = "🔥 [" ~ t ~ "] Kitchen Smoke Detected" %}
{% elif trigger.entity_id == "binary_sensor.saros_z70_water_shortage" %}
  {% set msg = "💧 [" ~ t ~ "] Saros Z70: No Clean Water" %}
{% elif trigger.entity_id == "binary_sensor.saros_z70_dock_clean_water_box" %}
  {% set msg = "💧 [" ~ t ~ "] Saros Z70: Clean Water Tank" %}
{% elif trigger.entity_id == "binary_sensor.saros_z70_dock_dirty_water_box" %}
  {% set msg = "⚠️ [" ~ t ~ "] Saros Z70: Dirty Water Tank" %}
{% elif trigger.entity_id == "sensor.saros_z70_vacuum_error" %}
  {% set msg = "⚠️ [" ~ t ~ "] Saros Z70: " ~ (trigger.to_state.state | replace("_", " ") | title) %}
{% elif trigger.entity_id == "sensor.bedroom_roborock_vacuum_cleaner_operational_error" %}
  {% set msg = "⚠️ [" ~ t ~ "] Bedroom Vacuum: " ~ (trigger.to_state.state | replace("_", " ") | title) %}
{% else %}
  {% set msg = "⚠️ [" ~ t ~ "] " ~ trigger.to_state.name %}
{% endif %}
{% set current = states("input_text.recent_alerts_24h") %}
{% if current in ["unknown", "unavailable", "", "none"] %}
  {{ msg }}
{% else %}
  {{ (msg ~ "   •   " ~ current)[:250] }}
{% endif %}
